using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InspectSkillFacing{
public static object Run(){var result=new List<object>();foreach(string name in new[]{"Running Knight Preview","Attack 05 - Skill_03","New Knight Combo Sequence Preview"}){var live=GameObject.Find(name);var root=UnityEngine.Object.Instantiate(live);try{root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;var c=a.runtimeAnimatorController.animationClips[0];var ts=a.GetComponentsInChildren<Transform>();Func<string,Transform> b=n=>ts.First(t=>t.name==n);foreach(int frame in new[]{0,4,8,12,16}){c.SampleAnimation(a.gameObject,frame/30f);var shoulder=Vector3.ProjectOnPlane(Vector3.Cross(b("RightUpperArm").position-b("LeftUpperArm").position,Vector3.up),Vector3.up).normalized;var hip=Vector3.ProjectOnPlane(Vector3.Cross(b("RightUpperLeg").position-b("LeftUpperLeg").position,Vector3.up),Vector3.up).normalized;result.Add(new{name,frame,shoulderYaw=Vector3.SignedAngle(Vector3.forward,shoulder,Vector3.up),hipYaw=Vector3.SignedAngle(Vector3.forward,hip,Vector3.up),modelRotation=a.transform.localEulerAngles.ToString()});}}finally{UnityEngine.Object.DestroyImmediate(root);}}return result;}}
